def divide_first_even_odd(lst):
    """
    Finds the first even number and the first odd number in the given list,
    then returns their division (even / odd).
    If either is missing, returns None.
    """
    even = None
    odd = None

    for num in lst:
        if even is None and num % 2 == 0:
            even = num
        if odd is None and num % 2 != 0:
            odd = num
        if even is not None and odd is not None:
            break

    if even is None or odd is None:
        return None
    return even / odd
```
